const BASE = document.body.dataset.page === 'home' ? '' : '../';
const page = document.body.dataset.page || 'home';
const esc = s => String(s ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtSize = n => n>=1024*1024 ? (n/1024/1024).toFixed(1)+' МБ' : Math.round(n/1024)+' КБ';
async function load(path){const r=await fetch(BASE+path+'?v=20261115school'); if(!r.ok) throw new Error(path); return r.json();}
function linkFor(doc){return doc.path ? BASE+doc.path : (doc.preview ? BASE+doc.preview : '#');}
function navHtml(nav){return nav.map(n=>n.group?`<div class="nav-group">${esc(n.group)}</div>${n.items.map(i=>navItem(i)).join('')}`:navItem(n)).join('')}
function navItem(i){let href=i.href.startsWith('pages/')?BASE+i.href:BASE+i.href; let active=(location.pathname.endsWith(i.href.split('/').pop()) || (i.href.includes('#')&&location.pathname.endsWith('calls.html')&&page==='calls'));return `<a href="${href}" class="${active?'active':''}"><span class="nav-icon">${i.icon||'·'}</span>${esc(i.label)}</a>`}
function shell(title,crumb,body,nav){return `<div class="shell"><aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-mark">T</div><div><div class="brand-name">АКАДЕМИЯ TOP</div><div class="brand-sub">База знаний · отдел продаж</div></div></div><nav class="nav">${navHtml(nav)}</nav><div class="sidebar-foot">Внутренний справочник отдела продаж<br>Версия сайта: рабочая сборка</div></aside><main class="main"><header class="topbar"><div style="display:flex;align-items:center;gap:12px"><button class="mobile-menu" id="menu">☰</button><div class="crumb">База знаний / ${esc(crumb||title)}</div></div><div class="top-actions"><div class="searchbox"><span class="search-icon">⌕</span><input id="globalSearch" placeholder="Поиск по базе знаний…" autocomplete="off"><div id="searchResults" class="search-results"></div></div></div></header><div class="content">${body}<div class="footer"><span>АКАДЕМИЯ TOP · БАЗА ЗНАНИЙ ОТДЕЛА ПРОДАЖ</span><span>Материалы представлены в исходном виде</span></div></div></main></div>`}
function docCard(d){let download=d.path?`<a class="muted" href="${BASE+d.path}" download>Скачать оригинал</a>`:'';let badge=d.status==='preview_only_large_original'?'Веб-копия':d.format;return `<article class="doc-card"><div class="file-icon">${esc(badge)}</div><div class="doc-meta"><h3>${esc(d.name)}</h3><p>${esc(d.description)} · ${esc(d.size_label)}${d.pages?` · ${d.pages} стр.`:''}</p><div class="doc-actions"><a href="doc-${d.id}.html">Открыть материал</a>${download}${d.status==='preview_only_large_original'?'<span class="pill">Оригинал больше лимита GitHub 100 МБ</span>':''}</div></div></article>`}
function docsSection(docs){if(!docs.length)return `<div class="empty">В этом разделе пока нет прикреплённых файлов.</div>`;return `<div class="doc-grid">${docs.map(docCard).join('')}</div>`}
function titleBlock(title,desc){return `<div class="page-title"><div class="eyebrow">Материалы Академии TOP</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>`}
function card(title,desc,href,icon='▣',pill='Раздел'){return `<a class="card" href="${href}"><div class="card-top"><div class="card-icon">${icon}</div><span class="pill">${pill}</span></div><h3>${esc(title)}</h3><p>${esc(desc)}</p><span class="card-link">Открыть раздел →</span></a>`}
function buildHome(docs,nav){const body=`<section class="hero"><div class="eyebrow">Корпоративная база знаний</div><h1>Единая система знаний<br>отдела продаж Академии TOP</h1><p>Рабочее пространство для изучения процессов продаж, быстрого доступа к инструкциям, скриптам, справочникам и исходным материалам.</p><div class="hero-actions"><a class="btn" href="pages/sources.html">Открыть реестр документов</a><a class="btn outline" href="pages/crm.html">Перейти к CRM</a></div></section><div class="stats"><div class="stat"><b>${docs.length}</b><span>исходных файлов в реестре</span></div><div class="stat"><b>8</b><span>разделов процессов продаж</span></div><div class="stat"><b>4</b><span>образовательных направления</span></div><div class="stat"><b>0</b><span>изменений в оригиналах</span></div></div><div class="section-head"><div><h2>Процессы продаж</h2><p>Основные этапы работы менеджера</p></div></div><div class="grid">${card('Звонки и скрипты','Первичный контакт, приглашение и сценарии звонков.','pages/calls.html','☎','Скрипты')}${card('Личные встречи','Структура визита, консультации и взрослый визит.','pages/visits.html','◉','Визит')}${card('Мастер-классы и ДОД','Регистрация, организация и сопровождение мероприятий.','pages/events.html','✦','Мероприятия')}${card('Работа в CRM','Регламент и материалы по ведению клиентской базы.','pages/crm.html','▦','CRM')}${card('Работа с возражениями','Исходный учебный материал по возражениям.','pages/objections.html','◇','Продажи')}${card('Договоры и оплаты','Материалы по обеспечительному платежу и оплатам.','pages/contracts.html','▤','Оформление')}${card('Шаблоны сообщений','Алгоритм коммуникации при первом контакте.','pages/messages.html','✉','Коммуникация')}${card('Справочники','Глоссарий и платформы для работы.','pages/references.html','⌕','Справка')}</div><div class="section-head"><div><h2>Образовательные направления</h2><p>Разделы с исходными программами и буклетами</p></div></div><div class="grid">${card('Детское дополнительное образование','Материалы МКА и детских программ.','pages/child-education.html','▣','Дети')}${card('Взрослое дополнительное образование','Буклеты и программы курсов.','pages/adult-education.html','▣','Взрослые')}${card('Колледж','Только образовательные программы колледжа.','pages/college.html','▣','Программы')}${card('ВУЗ','Бакалаврские программы и инфографика.','pages/university.html','▣','Программы')}</div><div class="notice"><b>Принцип работы с материалами.</b> Оригинальные файлы не редактируются. Навигационные названия и описания помогают найти документ, но не заменяют и не корректируют его содержание. Если исходный файл превышает ограничение GitHub в 100 МБ, в сайт помещена веб-копия для просмотра; оригинал в загруженных материалах не изменялся.</div>`;return shell('Обзор','Обзор',body,nav)}
function buildPage(slug,docs,nav,spec){let selected=docs.filter(d=>spec.categories.includes('ALL')||spec.categories.includes(d.category));let body=titleBlock(spec.title,spec.description);if(slug==='college'){body+=`<div class="notice"><b>Состав раздела:</b> только программы колледжа. Дополнительные инструкции и скрипты по колледжу находятся среди материалов по продажам, не в этом каталоге.</div>`;}if(slug==='crm'){body+=`<div class="notice"><b>Материалы CRM из переписки.</b> Дополнительно включён текст «Приоритеты работы CRM», переданный в чате. Он размещён отдельным файлом и не заменяет исходный регламент.</div><div class="card" style="margin-bottom:14px"><h3>Приоритеты работы CRM — текст из чата</h3><p>Отдельный исходный текстовый материал, переданный в переписке.</p><a class="card-link" href="crm-priorities.html">Открыть материал →</a></div>`;}if(slug==='references'){body+=`<div class="card" style="margin-bottom:16px"><h3>Платформы для работы</h3><div id="platformsTable"></div></div>`;}if(slug==='university'){body+=`<div class="notice">Инфографика добавлена как исходный визуальный материал. Сведения и статистика внутри изображения не редактировались и не проверялись.</div><img class="infographic" src="../assets/images/university-paths-infographic.png" alt="Инфографика об образовательных траекториях" style="margin:0 0 18px">`;}body+=`<div class="section-head"><div><h2>Исходные материалы</h2><p>${selected.length} файл(ов) в разделе</p></div></div>${docsSection(selected)}`;if(slug==='sources'){body+=`<div class="section-head"><div><h2>Полный реестр</h2><p>Фильтруйте документы по названию, категории и формату</p></div></div><div class="filters"><input id="sourceFilter" placeholder="Название или описание"><select id="categoryFilter"><option value="">Все категории</option>${[...new Set(docs.map(d=>d.category))].sort().map(c=>`<option>${esc(c)}</option>`).join('')}</select><select id="formatFilter"><option value="">Все форматы</option>${[...new Set(docs.map(d=>d.format))].sort().map(c=>`<option>${esc(c)}</option>`).join('')}</select></div><div id="sourceTable"></div>`;}return shell(spec.title,spec.title,body,nav)}
function buildCalls(docs,nav,spec){let body=titleBlock(spec.title,spec.description);body+=`<div class="notice">Сценарии звонков представлены отдельными исходными документами. Не объединяйте их в один универсальный скрипт: выбирайте материал по назначению контакта и ситуации.</div><div class="section-head"><div><h2>Сценарии звонков</h2><p>Исходные файлы</p></div></div>${docsSection(docs.filter(d=>d.category==='Звонки и скрипты'))}<div class="section-head anchor" id="repeat"><div><h2>Повторный контакт</h2><p>Отдельный сценарий повторной коммуникации</p></div></div>${docsSection(docs.filter(d=>d.category==='Повторный контакт'))}`;return shell(spec.title,spec.title,body,nav)}
function buildEvents(docs,nav,spec){let body=titleBlock(spec.title,spec.description);body+=`<div class="notice">Регламент записи, организация ивента, переориентир с МК на пробный урок и тестирование сохранены отдельными исходными материалами.</div>${docsSection(docs.filter(d=>d.category==='Мастер-классы и ДОД'))}`;return shell(spec.title,spec.title,body,nav)}
function buildReferences(docs,nav,spec){let body=titleBlock(spec.title,spec.description);body+=`<div class="card" style="margin-bottom:16px"><h2 style="font-size:16px;margin:0 0 12px">Платформы для работы</h2><div id="platformsTable"></div></div><div class="section-head"><div><h2>Глоссарий</h2><p>Исходный материал</p></div></div>${docsSection(docs.filter(d=>d.category==='Справочники'))}`;return shell(spec.title,spec.title,body,nav)}
function buildSources(docs,nav,spec){let body=titleBlock(spec.title,spec.description);body+=`<div class="notice">Названия файлов приведены в соответствии с загруженными материалами. Дублирующиеся файлы сохранены отдельными позициями. Оригиналы до 100 МБ включены в пакет сайта без изменений.</div><div class="filters"><input id="sourceFilter" placeholder="Поиск по названию или описанию"><select id="categoryFilter"><option value="">Все разделы</option>${[...new Set(docs.map(d=>d.category))].sort().map(c=>`<option>${esc(c)}</option>`).join('')}</select><select id="formatFilter"><option value="">Все форматы</option>${[...new Set(docs.map(d=>d.format))].sort().map(c=>`<option>${esc(c)}</option>`).join('')}</select></div><div id="sourceTable"></div>`;return shell(spec.title,spec.title,body,nav)}
function buildDocument(docs,nav,id){const d=docs.find(x=>x.id===id);if(!d)return shell('Материал','Материал','<div class="empty">Материал не найден.</div>',nav);const view=d.preview||d.path;let viewer='';if(d.format==='PNG'||d.format==='JPG'||d.format==='JPEG'){viewer=`<img class="infographic" src="../${view}" alt="${esc(d.name)}">`;}else if(view){viewer=`<iframe src="../${view}" title="${esc(d.name)}" style="width:100%;height:780px;border:0"></iframe>`;}else{viewer='<div class="empty">Предпросмотр для этого файла недоступен.</div>';}const notice=d.status==='preview_only_large_original'?'<div class="notice">Для просмотра в сайте используется веб-копия. Исходный PDF больше 100 МБ и не может быть загружен в GitHub как один файл. Оригинал не изменялся и остаётся в исходных материалах чата.</div>':'';const download=d.path?`<a class="btn" href="../${d.path}" download>Скачать исходный файл</a>`:'';const backMap={'Звонки и скрипты':'calls','Повторный контакт':'calls','Личные встречи':'visits','Мастер-классы и ДОД':'events','Работа в CRM':'crm','Работа с возражениями':'objections','Договоры и оплаты':'contracts','Шаблоны сообщений':'messages','Справочники':'references','Детское дополнительное образование':'child-education','Взрослое дополнительное образование':'adult-education','Колледж':'college','ВУЗ':'university'};const back=backMap[d.category]||'sources';let body=titleBlock(d.name,d.description)+`<div class="tagline"><span class="red-dot"></span>${esc(d.category)} · ${esc(d.format)} · ${esc(d.size_label)}${d.pages?` · ${d.pages} стр.`:''}</div>${notice}<div class="hero-actions"><a class="btn ghost" href="${back}.html">← Назад к разделу</a>${download}</div><div class="doc-viewer"><div class="doc-viewer-head"><span>Просмотр материала</span>${view?`<a href="../${view}" target="_blank">Открыть отдельно ↗</a>`:''}</div>${viewer}</div>`;return shell(d.name,d.category,body,nav)}
function platformHtml(rows){return `<div style="overflow:auto"><table class="source-table"><thead><tr><th>Название</th><th>Ссылка</th><th>Для чего используем</th><th>Как настроить</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r[0])}</b></td><td><a href="${esc(r[1])}" target="_blank" rel="noopener">Открыть</a></td><td>${esc(r[2])}</td><td>${esc(r[3]||'')}</td></tr>`).join('')}</tbody></table></div>`}
function tableHtml(rows){return `<div style="overflow:auto"><table class="source-table"><thead><tr><th>Файл</th><th>Раздел</th><th>Формат / размер</th><th>Действия</th></tr></thead><tbody>${rows.map(d=>`<tr><td><b>${esc(d.name)}</b><br><span style="color:#777">${esc(d.description)}</span></td><td>${esc(d.category)}</td><td>${esc(d.format)} · ${esc(d.size_label)}${d.pages?` · ${d.pages} стр.`:''}</td><td><a href="doc-${d.id}.html">Карточка</a>${d.path?` · <a href="${BASE+d.path}" download>Скачать</a>`:d.preview?` · <a href="${BASE+d.preview}" target="_blank">Веб-копия</a>`:''}</td></tr>`).join('')}</tbody></table></div>`}
async function main(){try{const [docs,nav,specs,platforms]=await Promise.all([load('data/documents.json'),load('data/navigation.json'),load('data/page-specs.json'),load('data/platforms.json')]);let html;if(page==='home')html=buildHome(docs,nav);else if(page==='crm-priorities')html=shell('Приоритеты работы CRM','Работа в CRM',titleBlock('Приоритеты работы CRM','Текст, переданный в чате, без изменения формулировок.')+`<div class="hero-actions"><a class="btn ghost" href="crm.html">← Назад к CRM</a></div><div class="prose" id="crm-priorities-content"></div>`,nav);else if(page==='doc')html=buildDocument(docs,nav,document.body.dataset.docId);else if(page==='calls')html=buildCalls(docs,nav,specs.calls);else if(page==='events')html=buildEvents(docs,nav,specs.events);else if(page==='references')html=buildReferences(docs,nav,specs.references);else if(page==='sources')html=buildSources(docs,nav,specs.sources);else html=buildPage(page,docs,nav,specs[page]||{title:'Раздел',description:'',categories:[]});document.getElementById('app').innerHTML=html;document.title=(page==='doc'?(docs.find(x=>x.id===document.body.dataset.docId)?.name||'Материал'):(page==='crm-priorities'?'Приоритеты работы CRM':(specs[page]?.title||'База знаний')))+' — Академия TOP';if(page==='crm-priorities'){fetch(BASE+'data/crm-priorities-rendered.html').then(r=>r.text()).then(h=>{document.getElementById('crm-priorities-content').innerHTML=h})}const menu=document.getElementById('menu');if(menu)menu.onclick=()=>document.getElementById('sidebar').classList.toggle('open');const pt=document.getElementById('platformsTable');if(pt)pt.innerHTML=platformHtml(platforms);const st=document.getElementById('sourceTable');if(st){const render=()=>{let q=(document.getElementById('sourceFilter').value||'').toLowerCase(),c=document.getElementById('categoryFilter').value,f=document.getElementById('formatFilter').value;let filtered=docs.filter(d=>(!q||(d.name+' '+d.description).toLowerCase().includes(q))&&(!c||d.category===c)&&(!f||d.format===f));st.innerHTML=tableHtml(filtered)};['sourceFilter','categoryFilter','formatFilter'].forEach(id=>document.getElementById(id).addEventListener(id==='sourceFilter'?'input':'change',render));render();}setupSearch(docs);}catch(e){document.getElementById('app').innerHTML='<div class="empty">Не удалось загрузить данные раздела. Проверьте, что сайт открыт через локальный сервер или GitHub Pages.</div>';console.error(e)}}
function setupSearch(docs){const input=document.getElementById('globalSearch'),results=document.getElementById('searchResults');if(!input||!results)return;let idx=[];fetch(BASE+'data/search-index.json').then(r=>r.json()).then(x=>idx=x).catch(()=>{});input.addEventListener('input',()=>{const q=input.value.trim().toLowerCase();if(q.length<2){results.classList.remove('show');return;}const found=idx.filter(d=>(d.name+' '+d.category+' '+d.description+' '+d.text).toLowerCase().includes(q)).slice(0,12);results.innerHTML=found.length?found.map(d=>{let doc=docs.find(x=>x.id===d.id);let target=doc?.preview||doc?.path;return `<a class="search-result" href="${BASE}pages/doc-${d.id}.html"><b>${esc(d.name)}</b><small>${esc(d.category)} · ${esc(d.description)}</small></a>`}).join(''):'<div class="search-result"><small>Ничего не найдено. Для сканированных PDF поиск по содержимому может быть недоступен.</small></div>';results.classList.add('show')});document.addEventListener('click',e=>{if(!e.target.closest('.searchbox'))results.classList.remove('show')});}
main();

/* Progressive UI enhancements. This layer keeps the original data and page rendering intact. */
(function enhanceUI(){
  const apply=()=>{
    const crumb=document.querySelector('.crumb');
    if(crumb && !crumb.querySelector('a')){
      const label=crumb.textContent.replace(/^\s*[^/]+\/\s*/, '');
      crumb.innerHTML=`<a href="${BASE}index.html" aria-label="На главную">${'База знаний'}</a><span aria-hidden="true"> / </span><span>${esc(label)}</span>`;
    }
    const menu=document.getElementById('menu');
    if(menu){menu.setAttribute('aria-label','Открыть меню');menu.setAttribute('aria-expanded',String(document.getElementById('sidebar')?.classList.contains('open')));if(!menu.dataset.enhanced){menu.dataset.enhanced='1';menu.addEventListener('click',()=>menu.setAttribute('aria-expanded',String(document.getElementById('sidebar')?.classList.contains('open'))));document.querySelectorAll('.sidebar a').forEach(a=>a.addEventListener('click',()=>{document.getElementById('sidebar')?.classList.remove('open');menu.setAttribute('aria-expanded','false')}));}}
    const results=document.getElementById('searchResults');
    if(results){results.setAttribute('aria-live','polite');results.setAttribute('aria-label','Результаты поиска');}
    const viewer=document.querySelector('.doc-viewer');
    if(viewer && !viewer.querySelector('.preview-close')){
      const back=document.querySelector('.hero-actions .ghost');
      const head=viewer.querySelector('.doc-viewer-head');
      if(head && back){const close=document.createElement('a');close.className='preview-close';close.href=back.getAttribute('href');close.textContent='Закрыть предпросмотр';head.appendChild(close);}
      const tag=document.querySelector('.tagline')?.textContent||'';
      if(/DOCX|PPTX|XLSX/i.test(tag)){
        viewer.querySelector('iframe')?.remove();
        const note=document.createElement('div');note.className='office-preview-note';note.innerHTML='<b>Встроенный просмотр недоступен для этого формата.</b><span>Скачайте оригинальный файл и откройте его в Microsoft Office или совместимом приложении.</span>';viewer.appendChild(note);
      }
    }
    const table=document.getElementById('sourceTable');
    if(table && !document.getElementById('sourceSort')){
      const filters=document.querySelector('.filters');
      if(filters){const sort=document.createElement('select');sort.id='sourceSort';sort.setAttribute('aria-label','Сортировка документов');sort.innerHTML='<option value="name">По названию</option><option value="category">По разделу</option><option value="format">По формату</option>';filters.appendChild(sort);sort.addEventListener('change',()=>{const rows=[...table.querySelectorAll('tbody tr')];const key=sort.value;rows.sort((a,b)=>{const ai=key==='category'?1:key==='format'?2:0;return (a.children[ai]?.textContent||'').localeCompare(b.children[ai]?.textContent||'','ru');});const body=table.querySelector('tbody');rows.forEach(r=>body.appendChild(r));});}
    }
  };
  const root=document.getElementById('app');
  if(root){new MutationObserver(apply).observe(root,{childList:true,subtree:true});apply();setTimeout(apply,500);setTimeout(apply,1500);}
})();

