(function collegeStudyPlans(){if(page!=='college')return;const plans=[['Специалист по работе с искусственным интеллектом','09.02.07 Информационные системы и программирование; квалификация в источнике: программист.','Общеобразовательный цикл; математика, информатика, физика; Python; базы данных; C++; разработка кода для обучения ИИ; обучение готовых моделей; основы генеративных моделей; этические аспекты ИИ.','Учебная и производственная практика; разработка программных модулей и мобильных приложений с поддержкой ИИ; тестирование модулей.','3 года 10 месяцев; очная и дистанционная формы указаны в источнике.','Демонстрационный экзамен и защита дипломного проекта; портфолио 19 проектов.'],['Реклама','42.02.01 Реклама; специалист по рекламе.','Общеобразовательный цикл; основы рисунка; дизайн-мышление; теория дизайна; маркетинг; медиапланирование; копирайтинг; цифровая реклама; социальные медиа; аналитика рекламы.','Учебная и производственная практика; индивидуальный проект; защита проекта.','2 года 10 месяцев; очная и дистанционная формы указаны в источнике.','Демонстрационный экзамен и защита дипломного проекта; портфолио указано в исходном плане.'],['Графический дизайн','Программа колледжа по графическому дизайну; точная квалификация в доступном извлечении не указана.','Общеобразовательный и общепрофессиональный циклы; основы рисунка; графический дизайн; компьютерная графика; дизайн-мышление; проектирование и визуальные коммуникации.','Учебная и производственная практика; проектные задания; формы контроля включают зачёты, экзамены и защиту проекта.','Не указано в доступном извлечении исходного материала.','Итоговая форма и портфолио требуют сверки с оригинальным PPTX.'],['Цифровая юриспруденция','Программа ЦЮ; точное наименование специальности и квалификация требуют сверки с оригинальным PPTX.','Правовые дисциплины, цифровая экономика, информационные технологии, документы и профессиональные модули указаны в учебном плане.','Учебная и производственная практика; проектная работа и контрольные мероприятия указаны в плане.','Не указано в доступном извлечении исходного материала.','Не указано в доступном извлечении исходного материала.'],['Разработка программного обеспечения','09.02.07 Информационные системы и программирование.','Программирование; базы данных; алгоритмизация; разработка и интеграция программных модулей; сопровождение ПО; администрирование и защита баз данных.','Учебная и производственная практика; интеграция программных модулей; сопровождение компьютерных систем; разработка и защита баз данных.','3 года 10 месяцев; формы обучения и контроль указаны в исходном плане.','Демонстрационный экзамен и защита дипломного проекта; портфолио 19 проектов.'],['Обеспечение информационной безопасности автоматизированных систем','10.02.05; техник по защите информации.','Операционные системы; архитектура аппаратных средств; основы информационной безопасности; компьютерные сети; криптографические средства; защита баз данных; техническая защита информации.','Учебная и производственная практика; эксплуатация защищённых автоматизированных систем; защита информации техническими средствами; работа оператором ЭВМ.','3 года 10 месяцев; очная и дистанционная формы указаны в источнике.','Демонстрационный экзамен и защита дипломного проекта; портфолио 15 проектов.']];const render=()=>{if(document.querySelector('.college-study-plans'))return;const anchor=document.querySelector('.section-head');if(!anchor)return;const s=document.createElement('section');s.className='college-study-plans';s.innerHTML=`<div class="section-head"><div><h2>Учебные планы программ колледжа</h2><p>Структура обучения, дисциплины и практические модули по представленным программам.</p></div></div><div class="notice">Информация собрана из исходных учебных материалов. Для официальной консультации необходимо использовать актуальную версию программы и документы Академии TOP.</div><div class="college-plans-table-scroll"><table class="college-plans-table"><thead><tr><th>Программа</th><th>Учебные дисциплины и модули</th><th>Практика и проекты</th><th>Продолжительность</th><th>Результат обучения</th></tr></thead><tbody>${plans.map(p=>`<tr>${p.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="college-plans-cards">${plans.map(p=>`<article class="college-plan-card"><h3>${esc(p[0])}</h3><p><b>Специальность:</b> ${esc(p[1])}</p><p><b>Дисциплины и модули:</b> ${esc(p[2])}</p><p><b>Практика и проекты:</b> ${esc(p[3])}</p><p><b>Продолжительность:</b> ${esc(p[4])}</p><p><b>Результат:</b> ${esc(p[5])}</p></article>`).join('')}</div>`;anchor.parentNode.insertBefore(s,anchor);};setTimeout(render,1400);setTimeout(render,2400);})();
(function collegeProvidedText(){if(page!=='college')return;const render=()=>{if(document.querySelector('.college-provided-text'))return;const anchor=document.querySelector('.college-study-plans')||document.querySelector('.section-head');if(!anchor)return;const b=document.createElement('section');b.className='college-provided-text';b.innerHTML=`<div class="section-head"><div><h2>09.02.07 Информационные системы и программирование — Программист</h2><p>Информация, предоставленная для раздела «Колледж».</p></div></div><div class="college-text-grid"><div><h3>Срок обучения</h3><p><b>На базе 9 классов:</b><br>РПО: 3 г. 10 мес.</p><p><b>На базе 11 классов:</b><br>РПО: 2 г. 10 мес.</p></div><div><h3>Количество учебных часов</h3><p><b>На базе 9 класса:</b><br>РПО — 5940 ак.час.</p><p><b>На базе 11 класса:</b><br>РПО — 4464 ак.час.</p></div></div><div class="college-text-section"><h3>Чему научится студент</h3><ul><li>Программировать на самых актуальных языках и технологиях;</li><li>Создавать базы данных и работать с ними;</li><li>Разрабатывать игры на телефон и компьютер;</li><li>Создавать облачные решения;</li><li>Научится алгоритмически мыслить.</li></ul><p>Программирование предоставляет самые широкие возможности в IT.</p></div><div class="college-text-section"><h3>Кем сможет работать выпускник</h3><ul><li>Программист;</li><li>Front-end, back-end, full-stack разработчик;</li><li>Java-программист;</li><li>.Net-разработчик;</li><li>Мобильный разработчик;</li><li>Разработчик компьютерных игр;</li><li>Тестировщик ПО;</li><li>Разработчик и администратор баз данных;</li><li>И многое другое.</li></ul></div>`;anchor.parentNode.insertBefore(b,anchor);};setTimeout(render,1500);setTimeout(render,2600);})();
(function collegeDesignerText(){if(page!=='college')return;const render=()=>{if(document.querySelector('.college-designer-text'))return;const anchor=document.querySelector('.college-study-plans')||document.querySelector('.section-head');if(!anchor)return;const b=document.createElement('section');b.className='college-designer-text';b.innerHTML=`<div class="section-head"><div><h2>Специальность 54.01.20 «Графический дизайнер»</h2><p>Дополнительная информация, предоставленная для раздела «Колледж».</p></div></div><div class="college-text-grid"><div><h3>Срок обучения</h3><p>На базе 9 классов — 2 г. 10 мес.<br>На базе 11 классов — 1 г. 10 мес.</p></div><div><h3>Документ об окончании</h3><p>Государственный диплом о среднем профессиональном образовании.</p></div></div><div class="college-text-section"><h3>Кем сможет работать выпускник</h3><ul><li>Графический дизайн</li><li>Интерьерный дизайн</li><li>Web-дизайн</li><li>Game Art Artist</li><li>3D-дизайнер и аниматор</li></ul></div><div class="college-text-section"><h3>Графический дизайнер занимается</h3><p>Стилистикой фирмы: логотипами, разработкой имиджа и корпоративными буклетами; всевозможным упаковочным материалом; визуальным взаимодействием с потребителем — в виде баннеров, растяжек и рекламы в интернете; информационной графикой: отчетами, презентациями и направлениями навигации.</p><h3>Должен знать</h3><ul><li>Photoshop, Adobe Illustrator и InDesign</li><li>Законы композиции</li><li>Колористика</li><li>Типографика</li><li>Маркетинг</li></ul></div><div class="college-text-section"><h3>Дизайнер интерьера</h3><p>Дизайнер интерьера — это специалист, который создает удобную и эстетически приятную атмосферу в помещении.</p><p>Дизайнеры интерьера требуются в разных областях: обустройство частных квартир и домов; торговые предприятия и компании; дизайн общественных помещений: кафе, ресторанов, салонов красоты, студий и т.д.</p><h3>Должен уметь</h3><ul><li>ArchiCad</li><li>3DMax</li><li>SketchUp</li><li>Adobe Photoshop</li></ul></div><div class="college-text-section"><h3>Веб-дизайнер</h3><p>Веб-дизайнер создаёт дизайн сайтов и приложений, но иногда под этим понимают сразу несколько задач: UI- и UX-дизайн, брендинг, дизайн лендингов.</p><h3>Должен знать</h3><ul><li>Дизайн-программы и редакторы</li><li>Adobe Illustrator или Photoshop</li><li>Основы UX- и UI-дизайна</li><li>Основы веб-аналитики</li><li>Основы анимации</li></ul></div><div class="college-text-section"><h3>Игровой художник (Game Artist)</h3><p>Игровой художник — это специалист в индустрии видеоигр, который отвечает за создание визуальной составляющей игры. Художники игр могут работать с любым игровым и анимационным программным обеспечением.</p><h3>Должен уметь</h3><ul><li>Adobe Photoshop, Иллюстратор</li><li>After Effects</li><li>3D Studio Max</li><li>Maya</li><li>Zbrush</li><li>CAD</li><li>Python</li><li>C++</li></ul></div><div class="college-text-section"><h3>3D-аниматор</h3><p>3D-аниматор — это специалист в области компьютерной графики, который занимается созданием анимированных изображений и сцен в трехмерном пространстве. 3D-аниматоры работают в различных сферах, таких как кинематограф, телевидение, видеоигры, реклама и мультимедиа.</p><h3>Должен знать</h3><ul><li>Blender</li><li>Autodesk 3DS Max</li><li>Autodesk Maya</li><li>Cinema 3D / 4D</li></ul></div>`;anchor.parentNode.insertBefore(b,anchor);};setTimeout(render,1800);setTimeout(render,3000);})();
(function collegeAIText(){if(page!=='college')return;const render=()=>{if(document.querySelector('.college-ai-text'))return;const anchor=document.querySelector('.college-study-plans')||document.querySelector('.section-head');if(!anchor)return;const b=document.createElement('section');b.className='college-ai-text';b.innerHTML=`<div class="section-head"><div><h2>Искусственный интеллект</h2><p>Информация, предоставленная для раздела «Колледж».</p></div></div><div class="college-text-grid"><div><h3>Специальность</h3><p>Интеграция решений с применением технологий искусственного интеллекта.</p><p><b>ФГОС:</b> 09.02.13</p><p><b>Квалификация:</b> Специалист по работе с искусственным интеллектом.</p></div><div><h3>Срок обучения и объем нагрузки</h3><p>На базе 9 классов — 3 года 10 месяцев, 5940 часов.</p><p>На базе 11 классов — 2 года 10 месяцев, 4464 часа.</p></div></div><div class="college-text-section"><h3>Кто это?</h3><p>Специалист по искусственному интеллекту — это профессионал, специализирующийся на разработке, обучении, адаптации и применении систем искусственного интеллекта (AI или ИИ) с целью создания интеллектуальных приложений и решений, которые могут автоматически анализировать данные, принимать решения, распознавать образы и выполнять другие задачи, традиционно требующие человеческого интеллекта.</p></div><div class="college-text-section"><h3>Чем занимается</h3><ul><li>Проводит аналитику и обработку больших данных.</li><li>Проектирует автоматизированные системы.</li><li>Внедряет искусственный интеллект в действующее программное обеспечение.</li><li>Модернизирует ресурсы и сервисы.</li><li>Создает графические и текстовые нейросети.</li><li>Тестирует прототипы и готовые модели.</li><li>Устанавливает и настраивает цифровые продукты.</li><li>Проводит рефакторинг программного кода.</li><li>Обучает роботизированные системы и нейросети.</li><li>Контролирует качество разработки с учетом российских и международных стандартов.</li></ul></div><div class="college-text-section"><h3>Чему научиться</h3><p>Формировать алгоритмы разработки программных модулей и разрабатывать программные модули в соответствии с техническим заданием.</p><p>Оформлять программный код в соответствии с техническим заданием и использовать систему контроля версий программного кода с учетом обеспечения возможности организации групповой разработки.</p><p>Выполнять отладку программных модулей с использованием специализированных программных средств, выполнять тестирование программного кода и составлять тестовые сценарии.</p><p><b>Администрирование баз данных:</b> выявлять проблемы, возникающие в процессе эксплуатации баз данных, осуществлять процедуры администрирования баз данных, проводить аудит систем безопасности баз данных и подготавливать данные для базы знаний.</p><p><b>Обучение готовых моделей искусственного интеллекта:</b> осуществлять выбор готовых моделей, формировать сценарии их обучения, проводить обучение и калибровку моделей, контролировать результат обучения, оформлять результат процедуры обучения и формировать запросы для работы с искусственным интеллектом с целью визуализации данных.</p></div><div class="college-text-section"><h3>Кому подойдет?</h3><p>Чтобы стать специалистом в области искусственного интеллекта, необходимо обладать аналитическим складом ума, усидчивостью и старательностью, креативностью, привычкой доводить дело до конца и умением мыслить нестандартно.</p></div><div class="college-text-section"><h3>Виды деятельности</h3><ul><li>Разработка кода для обучения искусственного интеллекта.</li><li>Администрирование баз данных.</li><li>Обучение готовых моделей искусственного интеллекта.</li></ul><h3>Где работает специалист</h3><p>Выпускники специальности «Интеграция решений с применением технологий искусственного интеллекта» будут востребованы практически в любой отрасли экономики, где сейчас активно используется и внедряется анализ данных и машинное обучение.</p></div><div class="college-text-section"><h3>Сколько зарабатывает?</h3><p>Начинающий специалист по ИИ (до 1–2 лет опыта): Москва и Санкт-Петербург — 80 000–150 000 рублей в месяц; регионы — 50 000–100 000 рублей в месяц.</p><p>Специалист по ИИ со средним опытом (2–5 лет опыта): Москва и Санкт-Петербург — 150 000–300 000 рублей в месяц; регионы — 100 000–200 000 рублей в месяц.</p><p>Опытный специалист по ИИ (более 5 лет опыта или специалист с глубокой специализацией): Москва и Санкт-Петербург — от 300 000 до 600 000 рублей и выше в месяц; регионы — 200 000–400 000 рублей в месяц и выше.</p><p>Ведущие специалисты по ИИ или руководители направления ИИ: Москва и Санкт-Петербург — от 500 000 до 1 000 000 рублей и выше в месяц; регионы — от 300 000 до 700 000 рублей и выше в месяц.</p></div><div class="college-text-section"><h3>Документ об образовании</h3><p>Государственный диплом с присвоением квалификации «Специалист по работе с искусственным интеллектом».</p></div>`;anchor.parentNode.insertBefore(b,anchor);};setTimeout(render,2000);setTimeout(render,3200);})();
(function collegeLawText(){if(page!=='college')return;const render=()=>{if(document.querySelector('.college-law-text'))return;const anchor=document.querySelector('.college-study-plans')||document.querySelector('.section-head');if(!anchor)return;const b=document.createElement('section');b.className='college-law-text';b.innerHTML=`<div class="section-head"><div><h2>Цифровой юрист</h2><p>Информация, предоставленная для раздела «Колледж».</p></div></div><div class="college-text-grid"><div><h3>Специальность</h3><p>Цифровой юрист / юриспруденция в ИТ.</p><p><b>ФГОС:</b> 40.02.04 Юриспруденция.</p><p><b>Квалификация:</b> Юрист.</p></div><div><h3>Срок обучения и объем нагрузки</h3><p>На базе 9 классов — 2 года 10 месяцев, 4428 часов.</p><p>На базе 11 классов — 1 год 10 месяцев, 2952 часа.</p></div></div><div class="college-text-section"><h3>Кто это?</h3><p>Цифровой юрист — это специалист в области права, специализирующийся на вопросах, связанных с цифровыми технологиями, интернетом и информационными системами.</p></div><div class="college-text-section"><h3>Чем занимается</h3><ul><li>Консультации по защите данных.</li><li>Разработка правовой документации.</li><li>Консультации по интеллектуальной собственности.</li><li>Урегулирование споров.</li><li>Консультации по электронной коммерции.</li><li>Соответствие нормативным требованиям.</li><li>Консультации по кибербезопасности.</li><li>Управление юридическими рисками.</li><li>Обучение и повышение осведомленности.</li><li>Мониторинг законодательства.</li></ul><p>Цифровой юрист должен сочетать глубокие знания в области права с пониманием специфики работы цифровых платформ, технологий и бизнес-моделей.</p></div><div class="college-text-section"><h3>Чему научиться</h3><ul><li>Техническая грамотность: основные принципы IT, кибербезопасности, блокчейна и других технологических инноваций.</li><li>Аналитические способности.</li><li>Защита данных и кибербезопасность.</li><li>Искусственный интеллект и автоматизация.</li><li>Коммуникационные навыки.</li><li>Гибкость и адаптивность.</li><li>Понимание этики.</li><li>Проактивность и творческое мышление.</li></ul></div><div class="college-text-section"><h3>Кому подойдет?</h3><p>Профессия юриста подойдет тем, кто интересуется правом и общественными отношениями, кому интересна сфера информационных технологий, кто хочет помогать людям и защищать их права, готов постоянно учиться и развиваться, обладает логическим мышлением, вниманием к деталям, умением аргументировать и убеждать, способен работать под давлением и сроками, коммуникабелен и ответственен.</p></div><div class="college-text-section"><h3>Специализации</h3><ul><li>Право в области защиты данных и конфиденциальности.</li><li>Кибербезопасность и информационная безопасность.</li><li>Интеллектуальная собственность в цифровой среде.</li><li>Электронная коммерция и цифровой бизнес.</li><li>Технологические стартапы и инновации.</li><li>Цифровые медиа и авторское право.</li><li>Блокчейн и криптовалюты.</li><li>Искусственный интеллект и машинное обучение.</li><li>Регулирование интернета и свобода выражения мнений.</li></ul></div><div class="college-text-section"><h3>Где работает специалист</h3><ul><li>Юридические фирмы.</li><li>Корпоративный сектор.</li><li>Государственные органы и регуляторы.</li><li>Образовательные и научно-исследовательские учреждения.</li><li>Некоммерческие организации и фонды.</li><li>Стартапы и инновационные компании.</li><li>Фриланс и самозанятость.</li></ul></div><div class="college-text-section"><h3>Сколько зарабатывает?</h3><p>Средняя зарплата IT-юриста — 150 000 рублей. Специалистам без опыта работодатели в Москве предлагают до 80 000 рублей. Профессионалы с опытом от 6 лет зарабатывают в корпорациях и крупных проектах до 350 000 рублей.</p></div><div class="college-text-section"><h3>Документ об образовании</h3><p>Государственный диплом с присвоением квалификации «Юрист».</p></div>`;anchor.parentNode.insertBefore(b,anchor);};setTimeout(render,2200);setTimeout(render,3400);})();
(function collegePlanWindows(){if(page!=='college')return;const run=()=>{const block=document.querySelector('.college-study-plans'),table=block?.querySelector('.college-plans-table tbody');if(!block||!table||block.dataset.windows)return;block.dataset.windows='1';const sourceNames=['Учебный план ГД 2.10 (1) (2).pptx','Учебный план РПО (1) (1) (1).pptx','Учебный план ИИ (1).pptx','Учебный план ИМ (1).pptx','Учебный план КБ.pptx','Учебный план ЦЮ1.pptx'];fetch(BASE+'data/documents.json?v=20261115').then(r=>r.json()).then(docs=>{const rows=[...table.querySelectorAll('tr')];const cards=document.createElement('div');cards.className='college-plan-windows';rows.forEach((tr,i)=>{const cells=[...tr.children].map(x=>x.innerText);const doc=docs.find(d=>d.name===sourceNames[i]);const det=document.createElement('details');det.className='college-plan-window';det.innerHTML=`<summary><span>${esc(cells[0]||'Программа колледжа')}</span><b>Показать подробный план</b></summary><div class="college-plan-window-body"><p><b>Специальность:</b> ${esc(cells[0]||'Не указано в исходном материале')}</p><p><b>Учебные дисциплины и модули:</b><br>${esc(cells[1]||'Не указано в исходном материале')}</p><p><b>Практика и проекты:</b><br>${esc(cells[2]||'Не указано в исходном материале')}</p><p><b>Продолжительность:</b><br>${esc(cells[3]||'Не указано в исходном материале')}</p><p><b>Результат обучения:</b><br>${esc(cells[4]||'Не указано в исходном материале')}</p>${doc?`<div class="college-plan-source"><b>Учебный план:</b><a href="../${doc.path}" target="_blank" rel="noopener">Открыть источник</a><a href="../${doc.path}" download>Скачать оригинал</a></div>`:''}<button type="button" class="btn ghost plan-close">Свернуть</button></div>`;det.querySelector('.plan-close').addEventListener('click',()=>det.removeAttribute('open'));cards.appendChild(det);});block.querySelector('.college-plans-table-scroll')?.replaceWith(cards);block.querySelector('.college-plans-cards')?.remove();});};setTimeout(run,3200);setTimeout(run,4800);})();
(function collegeAdmissionRules(){if(page!=='college')return;const render=()=>{if(document.querySelector('.college-admission-window'))return;const anchor=document.querySelector('.college-study-plans')||document.querySelector('.section-head');if(!anchor)return;const d=document.createElement('details');d.className='college-admission-window college-plan-window';d.innerHTML=`<summary><span>Правила приёма</span><b>Показать правила</b></summary><div class="college-plan-window-body"><h3>При приеме на обучение проводятся вступительные испытания</h3><ul><li>Собеседование по выявлению уровня психологической готовности потенциального студента к интенсивному обучению и самомотивации, самоорганизации;</li><li>Вступительное тестирование по основам компьютерной грамотности;</li><li>Тест на мотивацию для абитуриентов.</li></ul><h3>Прием документов поступающих</h3><p>Прием документов начинается не позднее 20 июня.</p><p>Прием заявлений в образовательные организации на очную форму обучения осуществляется до 15 августа, а при наличии свободных мест в образовательной организации прием документов продлевается до 25 ноября текущего года.</p><p>При подаче заявления на русском языке о приеме в колледж поступающий предъявляет следующие документы.</p><h3>Граждане Российской Федерации</h3><ul><li>Оригинал или копию документов, удостоверяющих его личность, гражданство;</li><li>Оригинал или копию документа об образовании и (или) документа об образовании и о квалификации;</li><li>Страховое свидетельство обязательного пенсионного страхования (при наличии);</li><li>4 фотографии размером 3×4;</li><li>Медицинская справка по форме 086-у;</li><li>Заявление на прием (приложение к договору в СРМ).</li></ul><button type="button" class="btn ghost admission-close">Свернуть</button></div>`;d.querySelector('.admission-close').addEventListener('click',()=>d.removeAttribute('open'));anchor.parentNode.insertBefore(d,anchor);};setTimeout(render,1800);setTimeout(render,3000);})();
(function collegeForeignersWindow(){if(page!=='college')return;const render=()=>{if(document.querySelector('.college-foreigners-window'))return;const anchor=document.querySelector('.college-study-plans')||document.querySelector('.section-head');if(!anchor)return;const d=document.createElement('details');d.className='college-foreigners-window college-plan-window';d.innerHTML=`<summary><span>Оформление иностранцев</span><b>Показать информацию</b></summary><div class="college-plan-window-body"><p>Гражданин другой страны может быть принят на обучение при условии легального нахождения в РФ: регистрация, вид на жительство, разрешенное время нахождения до 90 дней.</p><p>Мы не предоставляем патент студенческий, позволяющий за счёт обучения у нас находиться в РФ. Если студент получил аттестат, например в Казахстане, и переезжает в РФ на легальных условиях без нашего участия, тогда конечно.</p><p>Вопрос только в том, подлежит ли аттестат нострификации. Вопрос о нострификации рассматривается отдельно по каждой стране.</p><p>Для некоторых стран нотариального перевода будет недостаточно. Дополнительно нужна нострификация аттестата (апостиль).</p><h3>Апостилирование</h3><p>Апостилирование диплома — подтверждение юридической силы (то есть легализация) российского диплома об образовании в других странах. По сути, апостиль — это штамп, подтверждающий, что ваш диплом не поддельный.</p><h3>Нострификация</h3><p>Нострификация — процедура признания образования (или квалификации), полученного в иностранном государстве. Делается для того, чтобы признать, соответствует ли полученное образование (или квалификация) нормам иностранного государства.</p><p>В России нострификацию диплома об иностранном образовании делает «Главэкспертцентр».</p><h3>Способы подачи заявления</h3><ol><li>Лично в офисе: 119049, Москва, Ленинский проспект, д. 2А (этаж 6А). Адрес лучше заранее уточнить на сайте.</li><li>По почте.</li><li>Через личный кабинет на сайте «Главэкспертцентра».</li><li>Через портал «Госуслуги» — услуга «Признание иностранных документов об образовании».</li></ol><p>На сайте <a href="https://nic.gov.ru/ru/help/analyze" target="_blank" rel="noopener">nic.gov.ru/ru/help/analyze</a> проверяем, нужна ли нострификация, а на странице <a href="https://nic.gov.ru/ru/proc/lega" target="_blank" rel="noopener">nic.gov.ru/ru/proc/lega</a> смотрим, нужна ли легализация или проставление апостиля.</p><p>Все документы на иностранном языке должны быть переведены и нотариально заверены.</p><p>Чтобы проверить, нужна ли нострификация, необходимо знать дату выдачи документа: некоторые соглашения между странами утратили силу с определённой даты. Например, аттестат, полученный до декабря 2022 года, признаётся в РФ, а с декабря требует нострификации.</p><button type="button" class="btn ghost foreign-close">Свернуть</button></div>`;d.querySelector('.foreign-close').addEventListener('click',()=>d.removeAttribute('open'));anchor.parentNode.insertBefore(d,anchor);};setTimeout(render,2000);setTimeout(render,3400);})();
(function collegeStateSupportWindow(){if(page!=='college')return;const render=()=>{if(document.querySelector('.college-state-support-window'))return;const anchor=document.querySelector('.college-study-plans')||document.querySelector('.section-head');if(!anchor)return;const d=document.createElement('details');d.className='college-state-support-window college-plan-window';d.innerHTML=`<summary><span>Государственная поддержка</span><b>Показать информацию</b></summary><div class="college-plan-window-body"><p><b>Важно:</b> оформление льготного 3% кредита доступно только на специальности, на которые получена лицензия: РПО и КГиД. На новые специальности — Цифровой маркетинг, КБ, ЦЮ, ИИ — возможность будет доступна после получения лицензии.</p><h3>Образовательный кредит с господдержкой</h3><p>Клиент должен внести предоплату по выбранной форме оплаты. После поступления денег от Сбербанка излишне уплаченные средства возвращаем клиенту по его заявлению.</p><p><a href="https://itstepru-my.sharepoint.com/:f:/g/personal/ivanickay_v_top-academy_ru/ElG0-zW3EwBKnm69sxrcShgBhYR7Z7qOOwS9cK6ibCFi_w?e=8eoHKS" target="_blank" rel="noopener">Обучающие материалы для гос.поддержки, сертификат и QR-код для быстрой заявки</a></p><h3>Что это значит?</h3><p>Ставка по кредиту для студента — всего 3%. Остальную часть субсидирует государство. Кредит можно взять на оплату любого периода учёбы: один семестр, год или всё обучение целиком. Всё время учёбы и девять месяцев после неё нужно будет оплачивать только проценты по кредиту. Остальную сумму необходимо вернуть в течение 15 лет после того, как студент получит диплом. Кредит можно погасить досрочно.</p><p>Подать заявку на получение кредита можно не только в отделении Сбера, но и в самом учебном заведении. Кроме того, можно <a href="https://stats.ucheba.ru/link/ccb142" target="_blank" rel="noopener">оставить заявку на консультацию</a> с последующим обратным звонком специалиста банка.</p><p>Кредит оформляется на студента, но договор может быть оформлен на родителя по принципу «заказчик — родитель, а ребенок — студент и кредит берет именно он». Если студент несовершеннолетний, требуется согласие родителя.</p><p>Если вуз или колледж поднимет плату за обучение, банк выдаст дополнительную сумму, и вы сможете продолжить учиться как раньше.</p><p><b>Ежемесячно колледж отчитывается перед Министерством просвещения по студентам, оформившим льготный образовательный кредит.</b> Поэтому каждого студента, оформившего кредит, вносим в таблицу учета <a href="https://itstepru-my.sharepoint.com/:x:/g/personal/volchenkova_e_top-academy_ru/ERcExzarputLlOXQ87oP-6oB-pa9mVbgoLRNGOTTqpqngw?e=KvuAjX" target="_blank" rel="noopener">Кредит 2024</a>, предварительно создав вкладку на свой филиал.</p><button type="button" class="btn ghost state-support-close">Свернуть</button></div>`;d.querySelector('.state-support-close').addEventListener('click',()=>d.removeAttribute('open'));anchor.parentNode.insertBefore(d,anchor);};setTimeout(render,2200);setTimeout(render,3600);})();
(function collegeMaternityWindow(){if(page!=='college')return;const render=()=>{if(document.querySelector('.college-maternity-window'))return;const anchor=document.querySelector('.college-study-plans')||document.querySelector('.section-head');if(!anchor)return;const d=document.createElement('details');d.className='college-maternity-window college-plan-window';d.innerHTML=`<summary><span>Оформление колледжа по материнскому капиталу</span><b>Показать информацию</b></summary><div class="college-plan-window-body"><p><b>Важно:</b> оформление маткапитала доступно только на специальности, на которые получена лицензия: РПО и КГиД. На новые специальности — Цифровой маркетинг и Кибербезопасность — возможность будет доступна только после получения лицензии.</p><h3>Для филиалов, не открывающих направление колледжа в своем городе</h3><ol><li>Клиент должен внести предоплату по выбранной форме оплаты. После поступления денег от ПФР излишне уплаченные средства возвращаем клиенту по его заявлению или оставляем в счет оплаты следующего периода.</li><li>Оформление допускается только в филиал, имеющий головную лицензию на СПО: филиал Москва — АНО ПОО ММКЦТ «Академия ТОП». На колледже другое юридическое лицо.</li><li>Оформление договора на ИТ Колледж с гос. дипломом <b>в офлайне происходит в ЦРМ Колледжа Москвы</b>. Для доступа пишем запрос директору филиала Колледжа Москва: <a href="mailto:college_msk@top-academy.ru">college_msk@top-academy.ru</a>.</li><li>Оформление договора на онлайн-обучение происходит в ЦРМ Шамбалы. Для доступа в ЦРМ Шамбалы создаём запрос в <a href="https://jira.top-academy.ru/servicedesk/customer/portal/1/create/27" target="_blank" rel="noopener">Jira</a> в заверители Журавлеву Константину. Набор студентов: <a href="https://clck.ru/33oMtU" target="_blank" rel="noopener">ссылка</a>. Прайс Шамбалы: <a href="https://clck.ru/ec2PB" target="_blank" rel="noopener">ссылка</a>.</li><li>Дополнительно к договору оформляем дополнительное соглашение для ПФР из списка шаблонов в ЦРМ.</li><li>Подписываем документы с клиентом и высылаем сканы на <a href="mailto:college_msk@top-academy.ru">college_msk@top-academy.ru</a>, указав почтовый адрес филиала, ФИО и контакт ответственного за получение почты.</li><li>В течение 3 календарных дней в адрес филиала высылаются бумажные оригиналы подписанных документов.</li><li>После получения оригиналов передаем их клиенту для обращения в ПФР.</li></ol><h3>Для филиалов, открывающих направление колледжа</h3><ol><li>Клиент должен внести предоплату по выбранной форме оплаты. После поступления денег от ПФР излишне уплаченные средства возвращаем клиенту по его заявлению или оставляем в счет оплаты следующего периода.</li><li>Оформление допускается только в филиал, имеющий головную лицензию на СПО: филиал Москва — АНО ПОО ММКЦТ «Академия ТОП». На колледже другое юридическое лицо.</li><li>Для подписания договора маткапитал нужна доверенность. Если доверенности нет, запрашиваем её у экономиста и отправляем запрос региональным директорам.</li><li>Дополнительное соглашение для ПФР: <a href="https://itstepru-my.sharepoint.com/:w:/g/personal/ivanickay_v_top-academy_ru/ESQSa8uOzypKjh7ZFANij3gB5Q0gWMwVTT_fEWNPIB0osQ?e=5hHuwn" target="_blank" rel="noopener">открыть файл</a>. Адаптируем под свой филиал и загружаем в свою ЦРМ.</li><li>Договор и дополнительное соглашение подписываем с обеих сторон.</li><li>Готовим копию договора, дополнительного соглашения и <a href="https://itstepru-my.sharepoint.com/:b:/g/personal/volchenkova_e_top-academy_ru/EdelaDUn7n1FprLjaouvLasBUw9mkmE1oxvaj6iRemaoXw?e=5W2p1H" target="_blank" rel="noopener">лицензии</a>. Заверяем копии печатью/подписью колледжа и передаем клиенту для обращения в ПФР.</li></ol><button type="button" class="btn ghost maternity-close">Свернуть</button></div>`;d.querySelector('.maternity-close').addEventListener('click',()=>d.removeAttribute('open'));anchor.parentNode.insertBefore(d,anchor);};setTimeout(render,2400);setTimeout(render,3800);})();
(function collegeOrganizationWindow(){if(page!=='college')return;const render=()=>{if(document.querySelector('.college-organization-window'))return;const anchor=document.querySelector('.college-study-plans')||document.querySelector('.section-head');if(!anchor)return;const d=document.createElement('details');d.className='college-organization-window college-plan-window';d.innerHTML=`<summary><span>Организация обучения</span><b>Показать информацию</b></summary><div class="college-plan-window-body"><p>После того, как мы приняли абитуриента в колледж, он становится нашим студентом и тут начинается самое интересное. Обязательно делитесь этим с нашими абитуриентами, нужно заинтересовать подростка его же интересами.</p><h3>Вопросы и правила обучения в колледже</h3><ol><li>Что нужно приносить на пары? Стандартный набор канцелярии: ручка, тетрадка, остальное подскажет преподаватель.</li><li>Какая форма одежды? Формы нет, важно соблюдать опрятный внешний вид и нормы приличия.</li><li>Соблюдаем правила поведения в колледже: запрещено выражаться матом, приходить в состоянии алкогольного или наркотического опьянения, курить, в том числе электронные сигареты, портить имущество и проявлять любую форму агрессии.</li><li>Запрещено пропускать занятия без уважительной причины. Уважительная причина подтверждается справкой.</li><li>Важно выполнять домашние задания, работать на занятиях, сдавать зачеты и экзамены. Студент может быть отчислен из-за академической задолженности и/или за пропуски.</li><li>Студенты принимают участие в активностях и различных мероприятиях, организованных колледжем или самими студентами.</li></ol><h3>Как проходит обучение</h3><ol><li>Занятия проходят с понедельника по пятницу. Возможен гибридный вариант с добавлением дистанционных пар. Обучение возможно в две смены: самое раннее начало — с 08:00, самое позднее окончание пары — в 19:00. Нагрузка — до 18 пар (36 академических часов) в неделю.</li><li>Преподаватели современные и квалифицированные, проходят трехэтапный отбор.</li><li>Аудитории оборудованы современными компьютерами с необходимым программным обеспечением, лекционные аудитории комфортные и современные.</li></ol><h3>Цикл обучения</h3><h4>1. Общеобразовательный цикл (для студентов на базе 9-го класса)</h4><ul><li>Русский язык / литература</li><li>Химия / физика</li><li>Иностранный язык</li><li>История / обществознание</li><li>Физическая культура</li><li>ОБЗР</li><li>Биология / география</li><li>Математика / информатика</li><li>Индивидуальный проект</li></ul><p>Кроме данных дисциплин, на первом курсе включены профессиональные дисциплины в зависимости от направления обучения. Например, программисты начинают изучать язык программирования Python, а дизайнеры — Photoshop.</p><h4>2. Практическая подготовка</h4><p>Организуется со второго курса, проходит каждый семестр.</p><p><b>Учебная практика</b> — проходит в аудитории колледжа с преподавателем. Студент выполняет практические задания, готовит проекты.</p><p><b>Производственная практика</b> — проходит в организации-партнере под руководством сотрудника организации и кураторством преподавателя. Студенты выполняют реальные проекты на рабочем месте.</p><h4>3. Выпуск</h4><ol><li>Студент проходит преддипломную практику в IT-компании.</li><li>Сдает ГИА (государственную итоговую аттестацию).</li><li>Получает диплом государственного образца о среднем профессиональном образовании с присвоенной квалификацией.</li></ol><h3>Студенческая жизнь</h3><ol><li>День знаний 1 сентября: колледж организует мероприятие и активности для студентов — квиз, квест, концерт, выезд на природу и т.д.</li><li>День первокурсника в октябре или ноябре: мероприятие на сплочение групп.</li><li>Хэллоуин или осенний праздник: конкурс костюмов, украшение колледжа и совместный просмотр кино после пар.</li><li>Новогодняя вечеринка: празднование Нового года, украшение колледжа, фотозона и занятия в новогодних костюмах.</li><li>День влюбленных: валентинки, украшение колледжа и тематические активности.</li><li>Окончание учебного года и подведение итогов с вручением грамот за успехи среди студентов.</li></ol><p>Это только малая часть мероприятий, которые проходят в течение учебного года. Также студенты создают ежемесячный дайджест с событиями, успехами и переживаниями за прошедший период.</p><p>В колледже формируются студенческий совет, медиа-совет и клубы по интересам, например киберспорт или живопись на одежде. Каждый студент может проявить свои таланты и реализоваться не только в профессиональном ключе, но и прожить ярко, весело и интересно студенческие дни.</p><button type="button" class="btn ghost organization-close">Свернуть</button></div>`;d.querySelector('.organization-close').addEventListener('click',()=>d.removeAttribute('open'));anchor.parentNode.insertBefore(d,anchor);};setTimeout(render,2400);setTimeout(render,4000);})();
(function collegePageCleanup(){if(page!=='college')return;const clean=()=>{const content=document.querySelector('.content');if(!content||content.dataset.cleaned)return;content.dataset.cleaned='1';document.querySelectorAll('.section-intro .intro-materials,.section-intro').forEach(x=>x.remove());const title=document.querySelector('.page-title');if(!title)return;const toc=document.createElement('nav');toc.className='college-toc';toc.innerHTML='<b>На этой странице</b><a href="#college-info">О колледже</a><a href="#college-admission">Правила приёма</a><a href="#college-plans">Учебные планы</a><a href="#college-documents">Документы для ознакомления</a>';title.parentNode.insertBefore(toc,title.nextSibling);const firstText=document.querySelector('.college-provided-text');if(firstText){firstText.id='college-info';}const admission=document.querySelector('.college-admission-window');if(admission)admission.id='college-admission';const plans=document.querySelector('.college-study-plans');if(plans)plans.id='college-plans';const materials=document.querySelector('.materials');if(materials)materials.id='college-documents';const back=document.createElement('a');back.className='btn ghost college-back-link';back.href='../index.html';back.textContent='← Вернуться к образовательным направлениям';title.appendChild(back);};setTimeout(clean,4200);setTimeout(clean,6000);})();
(function collegeOnlyWindows(){if(page!=='college')return;const run=()=>{const content=document.querySelector('.content');if(!content||content.dataset.windowsOnly)return;const keep=el=>el.matches('.college-plan-windows,.college-admission-window,.college-foreigners-window,.college-state-support-window,.college-maternity-window,.college-organization-window,.college-study-plans')||el.querySelector('.college-plan-window');[...content.children].forEach(el=>{if(!keep(el)&&!el.classList.contains('footer'))el.style.display='none';});content.dataset.windowsOnly='1';};setTimeout(run,6500);setTimeout(run,8500);})();
(function universityStructured(){if(page!=='university')return;const programs=[['Дизайн','54.00.00 Изобразительное и прикладные виды искусств','Учебный план дизайна; соответствие программ СПО направлениям бакалавриата; дисциплины и практика указаны в исходных материалах.','Учебный план и проектная работа; точные параметры требуют сверки с источником.','Не указано в исходном материале.'],['Прикладная информатика','09.00.00 Информатика и вычислительная техника','Учебный план прикладной информатики; соответствие программ СПО направлениям бакалавриата; дисциплины и практика указаны в исходных материалах.','Учебный план и проектная работа; точные параметры требуют сверки с источником.','Не указано в исходном материале.']];const render=()=>{if(document.querySelector('.university-structured'))return;const anchor=document.querySelector('.section-head');if(!anchor)return;const s=document.createElement('section');s.className='university-structured';s.innerHTML=`<div class="section-head"><div><h2>О направлении</h2><p>Университет — направление высшего образования. В разделе собраны программы, учебные материалы и документы, которые помогают менеджеру ознакомиться с направлениями подготовки и представить их клиенту.</p></div></div><nav class="university-toc"><a href="#vuz-programs">Образовательные программы</a><a href="#vuz-docs">Документы и презентации</a><a href="#vuz-related">Связанные материалы</a></nav><div id="vuz-programs" class="section-head"><div><h2>Образовательные программы</h2><p>Программы, выделенные в предоставленных учебных материалах.</p></div></div><div class="university-program-cards">${programs.map(p=>`<article class="university-program-card"><h3>${esc(p[0])}</h3><p><b>Направление:</b> ${esc(p[1])}</p><p><b>Дисциплины:</b> ${esc(p[2])}</p><p><b>Практика и проекты:</b> ${esc(p[3])}</p><p><b>Результат:</b> ${esc(p[4])}</p></article>`).join('')}</div><div id="vuz-docs" class="section-head"><div><h2>Документы и презентации</h2><p>Исходные материалы университета доступны ниже в реестре страницы.</p></div></div><div id="vuz-related" class="notice">Связанные материалы: памятки приёмной комиссии, правила для иностранных граждан, льготное поступление, учебные планы и материалы по скидкам.</div>`;anchor.parentNode.insertBefore(s,anchor);};setTimeout(render,1600);setTimeout(render,3000);})();
(function universityConceptWindow(){if(page!=='university')return;const render=()=>{if(document.querySelector('.university-concept-window'))return;const anchor=document.querySelector('.university-structured')||document.querySelector('.section-head');if(!anchor)return;const d=document.createElement('details');d.className='university-concept-window college-plan-window';d.innerHTML=`<summary><span>Концепция ВУЗ</span><b>Показать информацию</b></summary><div class="college-plan-window-body"><h3>АНО ВО «Московский международный университет информационных технологий “Академия ТОП”»</h3><p><b>IT TOP University — это «Высшая лига» в сфере образования!</b></p><p><b>Целевая аудитория:</b> выпускники 11 классов, колледжей и вузов из России и других стран.</p><h3>Программы обучения</h3><p>Обучение осуществляется по программе высшего профессионального образования по направлениям бакалавриата:</p><p><b>09.03.03 «Прикладная информатика»:</b> профиль «Разработка программного обеспечения» (РПО) — включает области информационных технологий, связанные с искусственным интеллектом, устройством компьютера и компьютерным конструированием, распределенными вычислениями, базами данных, программной инженерией, гейм-разработкой, бизнес-аналитикой, робототехникой и др.</p><p><b>54.03.01 «Дизайн»:</b> профиль «Компьютерная графика и дизайн» (КГиД) — объединяет эстетику с техническими особенностями и задумки разработчиков с пользовательским спросом посредством разработки уникальных дизайн-проектов в любом жанре: айдентике, медиа-дизайне, веб-дизайне, дизайне упаковки, рекламной графике, UI-дизайне и др.</p><p>После успешного прохождения обучения выпускнику присваивается квалификация «бакалавр» и выдается диплом государственного образца.</p><h3>Формы обучения</h3><p>В ММУИТ обучение ведется в 2 формах:</p><ul><li><b>Очная:</b> продолжительность обучения — 4 года, учебный год длится 10 месяцев, график занятий включает 4–6 рабочих дней в неделю в 1 или 2 смену, доля контактной работы — 50% от общей трудоемкости учебного плана, предоставляется отсрочка от армии от вуза-партнера.</li><li><b>Очно-заочная:</b> продолжительность обучения — 4 года 6 месяцев, учебный год длится 10 месяцев, график занятий включает 3–4 рабочих дня в неделю с 18:00 до 21:00, доля контактной работы — 25%, отсрочка от армии не предоставляется.</li></ul><p>По любой из указанных форм можно пройти обучение с применением дистанционных технологий без изменения базовых параметров.</p><h3>Нормативное обеспечение</h3><p>Студенты всех форм обучения проходят программы по Федеральным государственным образовательным стандартам (ФГОС), на основе которых разработаны учебные планы Университета ТОП, что подтверждено бессрочной лицензией на право осуществления образовательной деятельности.</p><ul><li>ФГОС высшего образования — бакалавриат по направлению 09.03.03 «Прикладная информатика»;</li><li>ФГОС высшего образования — бакалавриат по направлению 54.03.01 «Дизайн»;</li><li>Лицензия ММУИТ;</li><li>Реестровая выписка (ВУЗ 08.12.25);</li><li>Основные профессиональные образовательные программы ММУИТ.</li></ul><h3>Управленческая структура</h3><ul><li>Директор по продукту: Андрей Сурович;</li><li>Директор по развитию офлайн-продуктов: Елена Волченкова;</li><li>Директор по развитию онлайн-продуктов: Светлана Калиничева;</li><li>Маркетолог-аналитик: Ольга Слим — slim_o@top-academy.ru.</li></ul><h3>Преимущества образовательных программ</h3><ol><li>Ориентация на серьезную практическую подготовку: практика, митапы с руководителями и специалистами ведущих предприятий.</li><li>Квалификация и компетентность преподавателей соответствует требованиям ФГОС и подтверждена их практической работой в отрасли.</li><li>Актуальная программа обучения сформирована при участии экспертов-практиков.</li><li>Соблюдается баланс управленческих дисциплин и глубокого освоения профильных навыков.</li><li>Обеспечивается возможность трудоустройства студентов во время обучения при лояльности и гибкости учебного графика.</li><li>Формируется портфолио специалиста по результатам выполнения проектных заданий.</li><li>Применяется геймификация учебного процесса и электронная образовательная среда.</li></ol><h3>Зачем выпускнику Колледжа ТОП поступать в Университет ТОП</h3><ol><li>Колледж ТОП дает современный инструментарий и практические навыки для работы по специальности. Его выпускники — профессиональные исполнители уровня Junior, но с ограниченным набором знаний и навыков.</li><li>Выпускники Университета ТОП получают более глубокие hard-skills, развивают soft-skills и общекультурные компетенции, становятся самостоятельными организаторами трудового процесса уровня Middle и руководителями коллективов уровня Senior.</li></ol><h3>Главный результат обучения в Университете ТОП</h3><p>Формирование высококвалифицированных специалистов с современным набором профессиональных знаний и навыков, развитыми способностями самостоятельных поисковых исследований, широким кругозором и стратегическим мышлением, которые готовы организовать собственный трудовой процесс и руководить коллективом.</p><button type="button" class="btn ghost university-concept-close">Свернуть</button></div>`;d.querySelector('.university-concept-close').addEventListener('click',()=>d.removeAttribute('open'));anchor.parentNode.insertBefore(d,anchor);};setTimeout(render,2200);setTimeout(render,3800);})();
(function universityProductWindow(){if(page!=='university')return;const render=()=>{if(document.querySelector('.university-product-window'))return;const anchor=document.querySelector('.university-concept-window')||document.querySelector('.university-structured')||document.querySelector('.section-head');if(!anchor)return;const d=document.createElement('details');d.className='university-product-window college-plan-window';d.innerHTML=`<summary><span>О продукте</span><b>Показать информацию</b></summary><div class="college-plan-window-body"><h3>Приоритет №1: Продажи и план набора</h3><p>Главный и единственный фокус на старте — выполнение плана по набору студентов. Все остальные вопросы — второстепенны.</p><p>Основная задача — сконцентрировать ресурсы на привлечении и заключении договоров с абитуриентами. Роль на старте — руководитель приемной кампании и организатор набора.</p><h3>Ключевые преимущества ВУЗа «Академия ТОП»</h3><ul><li><b>Практики из индустрии, а не теоретики:</b> преподаватели — работающие IT-специалисты и дизайнеры.</li><li><b>Интеграция в профессию с 1 курса:</b> практики, хакатоны, конкурсы проектов и портфолио.</li><li><b>Два диплома в одном пакете:</b> государственный диплом о высшем образовании и диплом о профессиональной переподготовке от «Академии ТОП».</li><li><b>Подготовка к руководящим ролям:</b> управленческие и экономические дисциплины.</li><li><b>Активная студенческая жизнь:</b> праздники, экскурсии, олимпиады, хакатоны и вебинары.</li></ul><h3>Важные уточнения по условиям поступления и обучения</h3><ol><li>Выпускники колледжей по профильным направлениям и выпускники вузов принимаются без ЕГЭ на основании диплома и внутренних испытаний. Выпускники колледжей по непрофильным направлениям поступают на основании ЕГЭ.</li><li>Аккредитация планируется к 2027 году. Условия для студентов 2026 года необходимо разъяснять по актуальной информации.</li><li>Государственный льготный кредит 3% недоступен при отсутствии аккредитации. Для дизайна указаны потребительский кредит, материнский капитал и налоговый вычет; по прикладной информатике условия кредитования нужно уточнять самостоятельно в банках.</li><li>На 2026/27 отсрочка от армии в ММУИТ не предоставляется; отсрочка возможна при зачислении в вуз-партнер при соблюдении условий.</li></ol><h3>Краткий итог для продаж</h3><p>Продавайте не просто образование, а карьерный старт. Главный козырь — практика, интеграция в индустрию и два диплома. Условия по финансам и отсрочке необходимо разъяснять точно.</p><p>Зачисление абитуриентов с законченным образованием СПО или ВО проводится на 1 курс с возможностью ускоренной формы обучения по дополнительному заявлению студента. В течение года студент должен ликвидировать академическую задолженность, возникшую из-за несовпадения учебных планов.</p><h3>Информация для поступающих по результатам ЕГЭ</h3><p>Приоритетность вступительных испытаний, предметы по выбору и профильная математика указаны в исходных материалах. Рисунок — творческое испытание, проводимое вузом самостоятельно.</p><h3>Информация для поступающих по результатам внутренних испытаний</h3><p>Приоритетность вступительных испытаний и расписание внутренних испытаний указаны в исходных материалах. Программы вступительных испытаний размещены на сайте <a href="https://top-university.ru/правила-приема-2026/" target="_blank" rel="noopener">«Правила приема 2026 — Университет TOP»</a>.</p><h3>Соответствие профиля СПО направлениям ВО</h3><p>Определение соответствия проводится по коду специальности в дипломе абитуриента. Для старых кодов и дипломов НПО необходимо ориентироваться на название специальности и современный аналог в таблицах соответствия.</p><p>Актуальные названия специальностей СПО: <a href="https://clck.ru/3StANo" target="_blank" rel="noopener">открыть справочник</a>.</p><h3>Участники СВО</h3><p>Результаты ЕГЭ и олимпиад для участников СВО действуют в год сдачи ЕГЭ или проведения олимпиады плюс четыре года, далее срок продлевается на период участия в СВО при документальном подтверждении.</p><button type="button" class="btn ghost university-product-close">Свернуть</button></div>`;d.querySelector('.university-product-close').addEventListener('click',()=>d.removeAttribute('open'));anchor.parentNode.insertBefore(d,anchor.nextSibling);};setTimeout(render,2600);setTimeout(render,4200);})();
(function universityPersonalFileWindow(){if(page!=='university')return;const render=()=>{if(document.querySelector('.university-personal-file-window'))return;const anchor=document.querySelector('.university-product-window')||document.querySelector('.university-concept-window')||document.querySelector('.university-structured');if(!anchor)return;const d=document.createElement('details');d.className='university-personal-file-window college-plan-window';d.innerHTML=`<summary><span>Формирование личного дела</span><b>Показать информацию</b></summary><div class="college-plan-window-body"><h3>Требования к качеству документов в бумажном и электронном виде для личного дела студента</h3><ol><li>Копируются все страницы, даже пустые, многостраничного документа вместе с приложениями, кроме паспорта.</li><li>В паспорте копируется только главный разворот и прописка.</li><li>На копии не должно быть теней, бликов, искривлений, пальцев и т.п.</li><li>Справка по форме 86У (для иностранцев — справка по форме 001-ИЗ и сертификат) и фотографии берутся в оригинале и в электронной копии.</li><li>Если абитуриент сдавал ЕГЭ по другому документу, удостоверяющему личность, надо взять данные другого документа.</li></ol><p><b>Важно:</b> если требования к качеству документов будут нарушены, то их невозможно будет занести в федеральный Суперсервис приема. То есть такого абитуриента можно потерять или спровоцировать недовольство при повторном запросе оригиналов документов для сканирования.</p><p>Личное дело студента формируется МОП в электронной папке и бумажной папке, которые передаются в учебную часть вуза после зачисления студента.</p><button type="button" class="btn ghost university-file-close">Свернуть</button></div>`;d.querySelector('.university-file-close').addEventListener('click',()=>d.removeAttribute('open'));anchor.parentNode.insertBefore(d,anchor.nextSibling);};setTimeout(render,2800);setTimeout(render,4400);})();
(function universityFaqWindow(){if(page!=='university')return;const render=()=>{if(document.querySelector('.university-faq-window'))return;const anchor=document.querySelector('.university-personal-file-window')||document.querySelector('.university-product-window')||document.querySelector('.university-concept-window');if(!anchor)return;const d=document.createElement('details');d.className='university-faq-window college-plan-window';d.innerHTML=`<summary><span>Часто задаваемые вопросы по договору</span><b>Показать вопросы и ответы</b></summary><div class="college-plan-window-body"><h3>1. Общие вопросы поступления</h3><p><b>Условия поступления 2026?</b></p><p><a href="https://top-university.ru/правила-приема-2026/" target="_blank" rel="noopener">ПРАВИЛА ПРИЕМА 2026 — Университет TOP</a></p><p><b>Как проходит поступление после окончания нашего Колледжа?</b><br>Для выпускников нашего Колледжа внутренним вступительным испытанием считается защита выпускной квалификационной работы (ВКР) колледжа и внутреннее собеседование.</p><p><b>Как проходит поступление после получения СПО или ВО?</b><br>С 01 сентября 2025 года: если направление подготовки в Университете профильное с полученным СПО или имеется ВО любого направления, абитуриент проходит внутренние вступительные испытания по дисциплинам, установленным Университетом. Если направление подготовки не профильное с полученным СПО/ВО, поступление осуществляется только по результатам ЕГЭ.</p><p><b>Нужен ли ЕГЭ по математике?</b><br>Для направления «Прикладная информатика» — профильный ЕГЭ по математике.</p><p><b>Я закончил школу несколько лет назад, мои результаты ЕГЭ старые. Что делать?</b><br>Для поступления на базе аттестата о среднем общем образовании обязательны актуальные результаты ЕГЭ. Срок действия результатов ЕГЭ — 4 года, следующих за годом сдачи. В 2026 году действительны результаты ЕГЭ 2022, 2023, 2024, 2025 и 2026 годов.</p><h3>2. Ускоренное обучение и перезачет дисциплин</h3><p><b>Предусмотрено ли ускоренное обучение для выпускников нашего Колледжа?</b><br>Да. Выпускники нашего Колледжа могут быть зачислены по программе ускоренного обучения, сокращенного на 1 год.</p><p><b>Предусмотрено ли ускоренное обучение для абитуриентов с дипломом ВО?</b><br>Да. Абитуриенты с дипломом ВО, поступающие на профильное направление, могут быть зачислены по программе ускоренного обучения. Точный срок определяется индивидуально после перезачета дисциплин.</p><p><b>Возможно ли ускоренное обучение для выпускников других колледжей?</b><br>Ускоренное обучение возможно для выпускников других колледжей только при поступлении на профильное направление и успешном прохождении внутренних вступительных испытаний. Точный срок определяется индивидуально после перезачета дисциплин.</p><p><b>Если зачтут часть дисциплин, будет ли стоимость обучения ниже?</b><br>Нет. Стоимость обучения остается полной за учебный год или семестр согласно утвержденному прейскуранту.</p><h3>3. Творческое испытание для направления «Дизайн»</h3><p>Для поступления на направление «Дизайн» предусмотрено творческое испытание в формате предоставления портфолио работ.</p><p>Абитуриент направляет PDF-файл, видео или фотографии своих работ: академический рисунок, живопись, графические работы, фотографии, батик, творчество в свободном жанре и т.п.</p><p>Максимальный балл за творческое испытание — 40 баллов.</p><h3>4. Прочее</h3><p><b>Предоставляется ли отсрочка от армии при обучении в ВУЗе?</b><br>Нет, Университет «Академия ТОП» не предоставляет отсрочку от призыва на военную службу для студентов очной формы обучения на 2026/27 год. После получения аккредитации отсрочка будет предоставляться для очного образования. Если студент зачисляется в вуз-партнер, ему предоставляется отсрочка от армии.</p><p>Отсрочка не предоставляется, если она уже была использована ранее при обучении по программам СПО или ВО.</p><button type="button" class="btn ghost university-faq-close">Свернуть</button></div>`;d.querySelector('.university-faq-close').addEventListener('click',()=>d.removeAttribute('open'));anchor.parentNode.insertBefore(d,anchor.nextSibling);};setTimeout(render,3000);setTimeout(render,4600);})();
(function universityAdmissionRulesWindow(){if(page!=='university')return;const render=()=>{if(document.querySelector('.university-admission-rules-window'))return;const anchor=document.querySelector('.university-faq-window')||document.querySelector('.university-product-window')||document.querySelector('.university-concept-window');if(!anchor)return;const d=document.createElement('details');d.className='university-admission-rules-window college-plan-window';d.innerHTML=`<summary><span>Правила приёма</span><b>Показать правила</b></summary><div class="college-plan-window-body"><h3>Приём на обучение</h3><ul><li>На первый курс.</li><li>При наличии среднего общего, среднего профессионального или высшего образования.</li><li>По договорам об образовании за счет средств физических и/или юридических лиц.</li><li>На конкурсной основе.</li><li>По результатам ЕГЭ, внутренних вступительных испытаний или без вступительных испытаний.</li></ul><p>Перевод из другого ВУЗа возможен после анализа справки об обучении аттестационной комиссией и рекомендации учебной части на любой курс без ограничений, но не ранее сдачи первой сессии. На момент перевода студент должен продолжать обучение.</p><h3>Подача заявления и документов</h3><p>Поступающий подает заявление о приеме на платные места и документы, необходимые для поступления.</p><p>Документы можно подать лично, через операторов почтовой связи (Почта России, СДЭК, Яндекс-Доставка) или посредством ЕПГУ.</p><h3>Документы, необходимые для поступления</h3><ul><li>Документ, удостоверяющий личность и гражданство.</li><li>Документ об образовании.</li><li>Для иностранного образования — свидетельство о признании, если оно требуется.</li><li>Документ регистрации в системе индивидуального учета (при наличии).</li><li>Согласие на обработку персональных данных.</li><li>Документы об инвалидности или ОВЗ при необходимости специальных условий.</li><li>Документ о централизованном тестировании или экзамене Республики Беларусь (если используется).</li><li>Документы об индивидуальных достижениях (по усмотрению поступающего).</li><li>Документы для иностранных граждан по международным договорам.</li><li>Для граждан РФ — медицинская справка по форме 86У.</li><li>Для иностранных граждан — форма № 001-ИЗ и сертификат об отсутствии ВИЧ.</li><li>Цветные фотографии 3×4 (4 шт.).</li><li>СНИЛС.</li><li>Приписное свидетельство или военный билет (при наличии).</li><li>Договор об оказании платных образовательных услуг.</li></ul><p>Документы на иностранном языке представляются с нотариально заверенным переводом на русский язык. Документы, полученные в иностранном государстве, должны быть легализованы, если иное не предусмотрено международным договором или законодательством РФ.</p><h3>Порядок проверки и личное дело</h3><p>Организация проверяет достоверность сведений в заявлении и подлинность документов, в том числе через государственные информационные системы и органы. Поступающий получает уникальный код на ЕПГУ или от организации. Личное дело формируется в электронной и/или бумажной форме.</p><p>Списки подавших заявление публикуются на официальном сайте и ЕПГУ и обновляются ежедневно при наличии изменений до публикации конкурсных списков.</p><h3>Основные этапы и даты поступления в 2026 году</h3><ol><li>Прием заявлений и документов: начало — 20 июня; со вступительными испытаниями — до 22 августа; без вступительных испытаний — до 26 августа.</li><li>Вступительные испытания: 23–26 августа.</li><li>Зачисление: публикация конкурсных списков — 27 августа; завершение заключения договоров — 28 августа до 12:00 по местному времени; приказы о зачислении — 31 августа.</li><li>Дополнительный прием для поступающих на основании иностранного документа об образовании — однократно не позднее 30 ноября.</li></ol><h3>Рекомендуемые документы</h3><ol><li>Приказ Минобрнауки России от 27 ноября 2024 г. № 821.</li><li>Правила приема в АНО ВО ММУИТ «Академия ТОП» на 2026/27 учебный год.</li></ol><button type="button" class="btn ghost university-admission-close">Свернуть</button></div>`;d.querySelector('.university-admission-close').addEventListener('click',()=>d.removeAttribute('open'));anchor.parentNode.insertBefore(d,anchor.nextSibling);};setTimeout(render,3200);setTimeout(render,4800);})();
(function universitySchoolAdmissionWindow(){if(page!=='university')return;const render=()=>{if(document.querySelector('.university-school-admission-window'))return;const anchor=document.querySelector('.university-admission-rules-window')||document.querySelector('.university-faq-window')||document.querySelector('.university-product-window');if(!anchor)return;const d=document.createElement('details');d.className='university-school-admission-window college-plan-window';d.innerHTML=`<summary><span>Поступление после школы (11 класса)</span><b>Показать информацию</b></summary><div class="college-plan-window-body"><h3>Виды вступительных испытаний</h3><p>Вузы устанавливают разные виды вступительных испытаний для абитуриентов со средним общим образованием, после профильного СПО, после непрофильного СПО и после высшего образования.</p><p>В 2026 году действительны результаты ЕГЭ 2022, 2023, 2024, 2025 и 2026 годов.</p><p>Результаты ЕГЭ и олимпиад школьников для участников СВО действуют в год сдачи плюс четыре года и далее продлеваются на период участия в СВО при документальном подтверждении. Срок продления должен включать последний день приема документов — 26 августа 2026 года.</p><h3>Для поступающих на базе среднего общего и непрофильного СПО</h3><p>Вступительные испытания проводятся по результатам ЕГЭ. Математика — профильный уровень. Рисунок — творческое испытание, проводимое вузом самостоятельно.</p><p>Сотрудник приемной комиссии предварительно проверяет результаты ЕГЭ на сайте <a href="https://checkege.rustest.ru/" target="_blank" rel="noopener">checkege.rustest.ru</a>; ответственный секретарь проверяет значения в ФИС ГИА и Приема.</p><p>Документы можно подать лично в приемной комиссии, через Госуслуги или по почте.</p><p>Абитуриент может подать документы одновременно в 5 вузов, в каждом выбрать до 5 направлений подготовки. Закон не запрещает одновременное освоение двух и более образовательных программ.</p><h3>Конкурсный список</h3><p>Все абитуриенты, подавшие документы на направление, включаются в единый конкурсный список. Список обновляется ежедневно и публикуется на сайте вуза и на Госуслугах. Абитуриенты располагаются по убыванию суммы конкурсных баллов. Для зачисления необходимо подать согласие на зачисление на конкретную специальность.</p><p>В Университете ТОП установлено ограничение по числу мест для зачисления на 2026/27 учебный год.</p><button type="button" class="btn ghost university-school-admission-close">Свернуть</button></div>`;d.querySelector('.university-school-admission-close').addEventListener('click',()=>d.removeAttribute('open'));anchor.parentNode.insertBefore(d,anchor.nextSibling);};setTimeout(render,3400);setTimeout(render,5000);})();
(function homeAcademyIntro(){if(page!=='home')return;const render=()=>{if(document.querySelector('.academy-intro'))return;const hero=document.querySelector('.hero');if(!hero)return;const section=document.createElement('section');section.className='academy-intro';section.innerHTML=`<div class="eyebrow">Об Академии TOP</div><h2>Академия TOP — единая образовательная экосистема</h2><p>Академия TOP объединяет детское и взрослое дополнительное образование, колледж, университет, мастер-классы и практические программы. Мы помогаем детям, подросткам и взрослым получать современные знания, развивать профессиональные навыки и выстраивать индивидуальную образовательную траекторию — от первого знакомства с профессией до системного обучения и профессионального развития.</p><p>Эта база знаний создана для сотрудников отдела продаж. Здесь собраны программы обучения, учебные планы, презентации, скрипты, регламенты, шаблоны сообщений и другие материалы, которые помогают правильно ориентироваться в образовательной экосистеме Академии TOP и консультировать клиентов.</p><p class="academy-intro-note">Используйте базу знаний для быстрого поиска информации о программах, процессах продаж и материалах для работы с клиентами.</p><div class="academy-tags"><a href="pages/child-education.html">Детское образование</a><a href="pages/adult-education.html">Взрослое образование</a><a href="pages/college.html">Колледж</a><a href="pages/university.html">Университет</a><a href="pages/events.html">Практические программы</a></div>`;hero.parentNode.insertBefore(section,hero.nextSibling);};setTimeout(render,1000);setTimeout(render,2200);})();
(function homeValues(){if(page!=='home')return;const render=()=>{const stats=document.querySelector('.stats');if(!stats||stats.dataset.values)return;stats.dataset.values='1';stats.innerHTML='<div class="stat value-stat"><b>Профессионализм</b><span>Компетентность команды и практический подход к обучению</span></div><div class="stat value-stat"><b>Современность</b><span>Актуальные знания, технологии и образовательные форматы</span></div><div class="stat value-stat"><b>Забота о студентах</b><span>Внимательное сопровождение на каждом этапе обучения</span></div>';stats.classList.add('values-stats');};setTimeout(render,1200);setTimeout(render,2400);})();
